def valid(ids):
    if len(ids) < min_c or len(ids) > max_c:
        return False
    selected = [o for o in options if o['id'] in ids]
    for field, bounds in sum_bounds.items():
        s = 0
        for o in selected:
            if field in o:
                s += o[field]
        if 'min' in bounds and s < bounds['min']:
            return False
        if 'max' in bounds and s > bounds['max']:
            return False
    for uf in unique_fields:
        vals = []
        for o in selected:
            if uf in o:
                vals.append(o[uf])
            else:
                vals.append(None)
        # Check uniqueness
        unique_vals = []
        for v in vals:
            if v in unique_vals:
                return False
            unique_vals.append(v)
    # no_conflicts false, closed_dependencies false, cover empty
    return True

for k in range(min_c, max_c + 1):
    # combinations is builtin
    for comb in combinations(sorted_opts, k):
        ids = []
